+                        "SELECT kind, request_execution_type, at FROM backtest_reuse_event"
+                                + " WHERE run_id = ?",
+                        runId);
+        assertThat(event.get("kind")).isEqualTo("JOINED");
+        assertThat(event.get("request_execution_type")).isEqualTo("SINGLE");
